# %% ../nbs/060_metrics.ipynb #925bfd79
class DiceFastaiMetric(FastaiMetricMixin, mm.DiceMetric):
    """
    Fastai-compatible adapter for MONAI's ``DiceMetric``.

    This class combines ``FastaiMetricMixin`` with MONAI's ``DiceMetric`` so
    that Dice computation remains fully delegated to MONAI while the metric
    exposes the interface required by the fastai training loop.

    Predictions produced by a fastai segmentation model are converted to the
    representation expected by MONAI before metric computation:

    * single-channel predictions are converted to binary masks using a
      sigmoid activation followed by a threshold of ``0.5``;
    * multi-channel predictions are converted to discrete class labels using
      ``argmax`` over the channel dimension;
    * targets without a channel dimension are expanded with a singleton
      channel dimension.

    All constructor arguments are forwarded directly to MONAI's
    ``DiceMetric``.

    Parameters
    ----------
    include_background : bool, default=True
        Whether to include the background class in the Dice computation.
    reduction : str, default="mean"
        Reduction method used to combine Dice scores.
    get_not_nans : bool, default=False
        Whether to return the number of non-NaN values used in the reduction.
    ignore_empty : bool, default=True
        Whether to ignore samples with an empty target segmentation.
    num_classes : int, optional
        Number of classes when using single-channel label maps.
    return_with_label : bool or list of str, default=False
        Whether to return Dice values together with their labels.
    per_component : bool, default=False
        Whether to compute Dice independently for each binary component.
    **kwargs
        Additional arguments accepted by MONAI's ``DiceMetric``.

    Notes
    -----
    The metric itself is implemented by MONAI. ``FastaiMetricMixin`` only
    provides the fastai metric lifecycle and calls ``_prepare`` before
    delegating to MONAI's ``__call__`` implementation.
    """

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._name = "Dice"

    def _prepare(self, pred, target):
        """
        Convert fastai predictions and targets to MONAI Dice inputs.

        Parameters
        ----------
        pred : torch.Tensor
            Model predictions. Expected shape is ``(B, C, ...)`` for
            channel-based segmentation outputs.
        target : torch.Tensor
            Ground-truth segmentation labels.

        Returns
        -------
        tuple
            Prepared ``(pred, target)`` pair suitable for MONAI's
            ``DiceMetric``.
        """
        # Binary segmentation: one output channel
        if pred.ndim == target.ndim + 1:
            if pred.shape[1] == 1:
                pred = (torch.sigmoid(pred) > 0.5).float()

            # Multi-class segmentation
            else:
                pred = pred.argmax(dim=1, keepdim=True)

        # Add channel dimension to label-map targets
        if target.ndim == pred.ndim - 1:
            target = target.unsqueeze(1)

        return pred, target

# %% ../nbs/060_metrics.ipynb #a63e7732
class DiceMetric(BioMetric):
    """
    Compute the Dice coefficient for segmentation tasks.

    The Dice coefficient measures the spatial overlap between predicted and
    target segmentations. The metric supports single-channel label maps for
    multi-class segmentation as well as multi-channel representations for
    class-wise or multi-label segmentation.

    Parameters
    ----------
    include_background : bool, default=True
        Whether to include the background channel in the computation.

    reduction : str, default="mean"
        Reduction method used to combine per-sample and per-channel Dice
        scores. Common options include ``"mean"``, ``"sum"``,
        ``"mean_batch"``, ``"sum_batch"``, and ``"none"``.

    get_not_nans : bool, default=False
        If ``True``, also return the number of non-NaN values used in the
        reduction.

    ignore_empty : bool, default=True
        Whether to ignore cases where the target segmentation is empty.
        If ``True``, empty target regions do not contribute to the metric.

    num_classes : int, optional
        Number of classes when the input is provided as a single-channel
        label map. This may be required when the number of classes cannot be
        inferred from the input.

    return_with_label : bool or list of str, default=False
        If ``True``, return Dice values together with their class labels.
        A list of labels can be provided to explicitly name the classes.

    per_component : bool, default=False
        If ``True``, compute the Dice score independently for each binary
        component.

    Examples
    --------
    Compute the mean Dice score while excluding the background::

        dice = DiceMetric(
            include_background=False,
            reduction="mean",
        )

    Compute per-class Dice scores::

        dice = DiceMetric(
            include_background=False,
            reduction="none",
        )

    Notes
    -----
    The default backend uses MONAI's ``DiceMetric`` implementation. The
    fastai backend uses ``DiceFastaiMetric``, which combines MONAI's metric
    implementation with ``FastaiMetricMixin`` to provide the interface
    required by the fastai training loop.
    """

    _default = mm.DiceMetric
    _fastai = DiceFastaiMetric

