class MetricsReloadedBinaryFastai(FastaiMetricMixin, mm.MetricsReloadedBinary):
    """
    Fastai-compatible adapter for MONAI's ``MetricsReloadedBinary``.

    This class combines ``FastaiMetricMixin`` with MONAI's
    ``MetricsReloadedBinary`` implementation. It adapts the target produced
    by fastai, which is stored in ``learn.yb`` as a tuple, to the tensor
    expected by the MONAI metric.

    Parameters
    ----------
    metric_name : str
        Name of the MetricsReloaded metric to compute.

    *args
        Positional arguments passed to ``MetricsReloadedBinary``.

    **kwargs
        Additional keyword arguments passed to
        ``MetricsReloadedBinary``.

    Notes
    -----
    The metric computation and aggregation are delegated entirely to MONAI.
    ``FastaiMetricMixin`` provides the fastai ``accumulate`` and ``value``
    interface.

    Only the first target in ``learn.yb`` is used.
    """

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._name = "MetricsReloadedBinary"

    def _prepare(self, pred, target):
        """
        Prepare predictions and targets for the MONAI metric.

        Parameters
        ----------
        pred : torch.Tensor
            Predictions produced by the fastai learner.

        target : tuple
            Targets stored by fastai in ``learn.yb``.

        Returns
        -------
        tuple
            Prepared ``(pred, target)`` pair.
        """
        return pred, target[0]

